PRAGMA foreign_keys = ON;
CREATE TABLE topics (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE content_assets (id TEXT PRIMARY KEY, topic_id TEXT REFERENCES topics(id), type TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, status TEXT NOT NULL DEFAULT 'published', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE free_tools (id TEXT PRIMARY KEY, topic_id TEXT REFERENCES topics(id), slug TEXT UNIQUE NOT NULL, version TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE visitors (id TEXT PRIMARY KEY, consent INTEGER NOT NULL CHECK(consent = 1), created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE sources (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE tool_sessions (id TEXT PRIMARY KEY, visitor_id TEXT REFERENCES visitors(id), tool_id TEXT REFERENCES free_tools(id), status TEXT NOT NULL CHECK(status IN ('started','completed')), created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE leads (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, source TEXT NOT NULL, campaign TEXT, consent INTEGER NOT NULL CHECK(consent = 1), status TEXT NOT NULL DEFAULT 'interested', created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE opportunities (id TEXT PRIMARY KEY, cluster TEXT NOT NULL, demand_source TEXT NOT NULL, demand_note TEXT NOT NULL, demand_score INTEGER NOT NULL CHECK(demand_score BETWEEN 0 AND 5), pain_score INTEGER NOT NULL CHECK(pain_score BETWEEN 0 AND 5), intent_score INTEGER NOT NULL CHECK(intent_score BETWEEN 0 AND 5), monetization_score INTEGER NOT NULL CHECK(monetization_score BETWEEN 0 AND 5), priority TEXT NOT NULL DEFAULT 'medium', status TEXT NOT NULL DEFAULT 'hypothesis', owner TEXT NOT NULL DEFAULT 'operator', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE products (id TEXT PRIMARY KEY, name TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount >= 0), currency TEXT NOT NULL, version TEXT NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE offers (id TEXT PRIMARY KEY, product_id TEXT REFERENCES products(id), status TEXT NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE customers (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE transactions (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id), product_id TEXT NOT NULL REFERENCES products(id), amount INTEGER NOT NULL CHECK(amount >= 0), currency TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','checkout','paid','failed','expired','refunded')), provider_session TEXT UNIQUE, provider_payment TEXT UNIQUE, refunded_amount INTEGER NOT NULL DEFAULT 0 CHECK(refunded_amount >= 0), checkout_url TEXT, idempotency_key TEXT UNIQUE NOT NULL, source TEXT NOT NULL DEFAULT 'direct', created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE fulfillments (id TEXT PRIMARY KEY, transaction_id TEXT UNIQUE NOT NULL REFERENCES transactions(id), status TEXT NOT NULL CHECK(status IN ('available','delivered','revoked')), created_at INTEGER NOT NULL DEFAULT (unixepoch()), delivered_at INTEGER);
CREATE TABLE subscriptions (id TEXT PRIMARY KEY, customer_id TEXT REFERENCES customers(id), product_id TEXT REFERENCES products(id), status TEXT NOT NULL DEFAULT 'not_launched', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE experiments (id TEXT PRIMARY KEY, hypothesis TEXT NOT NULL, metric TEXT NOT NULL, variant TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'planned', result_note TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE events (id TEXT PRIMARY KEY, name TEXT NOT NULL, session_id TEXT, source TEXT, page TEXT, tool TEXT, product TEXT, offer TEXT, campaign TEXT, device TEXT, transaction_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE next_actions (id TEXT PRIMARY KEY, title TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', owner TEXT NOT NULL DEFAULT 'operator', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE support_requests (id TEXT PRIMARY KEY, email TEXT NOT NULL, topic TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE access_tokens (hash TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('order','magic','session')), subject TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE webhook_receipts (id TEXT PRIMARY KEY, type TEXT NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE notifications (id TEXT PRIMARY KEY, transaction_id TEXT REFERENCES transactions(id), type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE rate_limits (id TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE maintenance (id TEXT PRIMARY KEY, last_run INTEGER NOT NULL);
CREATE INDEX idx_events_name_time ON events(name,created_at);
CREATE INDEX idx_events_session_time ON events(session_id,created_at);
CREATE INDEX idx_transactions_customer ON transactions(customer_id,created_at);
CREATE INDEX idx_tokens_expiry ON access_tokens(expires_at);
CREATE INDEX idx_rate_expiry ON rate_limits(expires_at);
